package app;

import app.repositories.AuditLogRepository;
import app.repositories.ProductRepository;
import app.repositories.MongoAuditLogRepository;
import app.repositories.MongoProductRepository;
import java.util.function.Function;
import org.springframework.data.mongodb.core.MongoTemplate;

/** The repositories over one MongoTemplate. */
public class MongoUnitOfWork implements UnitOfWork {
    private final MongoTemplate mongo;
    private final ProductRepository products;
    private final AuditLogRepository auditLog;

    public MongoUnitOfWork(MongoTemplate mongo) {
        this.mongo = mongo;
        this.products = new MongoProductRepository(mongo);
        this.auditLog = new MongoAuditLogRepository(mongo);
    }

    public MongoTemplate mongo() {
        return mongo;
    }

    @Override
    public ProductRepository products() {
        return products;
    }

    @Override
    public AuditLogRepository auditLog() {
        return auditLog;
    }

    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        return work.apply(this);
    }
}

