    private static List<Object> keyOf(AuditLog row) {
        List<Object> key = new ArrayList<>();
        key.add(row.getId());
        return key;
    }

    /** Orders two keys value by value. */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private static int compareKeys(List<Object> a, List<Object> b) {
        for (int index = 0; index < a.size(); index++) {
            int order = ((Comparable) a.get(index)).compareTo(b.get(index));
            if (order != 0) return order;
        }
        return 0;
    }

    private Stream<AuditLog> visible() {
        return rows.values().stream().filter((row) -> true).sorted(Comparator.comparing(MemoryAuditLogRepository::keyOf, MemoryAuditLogRepository::compareKeys));
    }

    @Override
    public Optional<AuditLog> findById(String id) {
        return visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
    }

    @Override
    public Page<AuditLog> list(int offset, int limit) {
        List<AuditLog> rows = visible().toList();
        return new Page<>(rows.stream().skip(offset).limit(limit).toList(), rows.size(), offset, limit);
    }

    @Override
    public AuditLog insert(AuditLog entity) {
