package app.repositories;

import app.Documents;
import app.common.Page;
import app.entities.AuditLog;
import com.mongodb.client.model.Filters;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.WeakHashMap;
import org.bson.Document;
import org.springframework.dao.DataAccessException;
import org.springframework.data.domain.Sort;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;

/** Keeps audit-log documents in the database, through a MongoTemplate. Every write is stored at once. */
public class MongoAuditLogRepository implements AuditLogRepository {
    /** The document each entity was read from: a change writes only the fields that differ */
    private static final Map<AuditLog, Document> LOADED = Collections.synchronizedMap(new WeakHashMap<>());

    /** The fields a change may write */
    private static final List<String> FIELDS = List.of("at", "by");

    private final MongoTemplate mongo;

    public MongoAuditLogRepository(MongoTemplate mongo) {
        this.mongo = mongo;
    }

    @Override
    public Optional<AuditLog> findById(String id) {
        AuditLog found = mongo.findOne(Query.query(Criteria.where("id").is(id)), AuditLog.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public Page<AuditLog> list(int offset, int limit) {
        List<AuditLog> items = mongo.find(new Query().with(Sort.by("id")).skip(offset).limit(limit), AuditLog.class).stream().map(this::loaded).toList();
        return new Page<>(items, mongo.count(new Query(), AuditLog.class), offset, limit);
    }

    @Override
    public AuditLog insert(AuditLog entity) {
        try {
            mongo.insert(entity);
        } catch (DataAccessException error) {
            throw Documents.refusal("AuditLog", error);
        }
        return loaded(entity);
    }

    @Override
    public AuditLog update(AuditLog entity) {
        Document now = Documents.of(mongo, entity);
        Document changes = Documents.changes(LOADED.get(entity), now, FIELDS);
        try {
            if (!changes.isEmpty()) mongo.execute(AuditLog.class, (collection) -> collection.updateOne(Filters.eq("_id", now.get("_id")), changes));
        } catch (DataAccessException error) {
            throw Documents.refusal("AuditLog", error);
        }
        return loaded(entity);
    }

    @Override
    public void delete(AuditLog entity) {
        try {
            mongo.remove(Query.query(Criteria.where("id").is(entity.getId())), AuditLog.class);
        } catch (DataAccessException error) {
            throw Documents.refusal("AuditLog", error);
        }
    }

    /** The same entity, with what it is stored as kept to tell its changes. */
    private AuditLog loaded(AuditLog entity) {
        LOADED.put(entity, Documents.of(mongo, entity));
        return entity;
    }
}

