        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public Page<Product> list(int offset, int limit) {
        List<Product> items = mongo.find(new Query().with(Sort.by("id")).skip(offset).limit(limit), Product.class).stream().map(this::loaded).toList();
        return new Page<>(items, mongo.count(new Query(), Product.class), offset, limit);
    }

    @Override
    public Product insert(Product entity) {
        try {
            mongo.insert(entity);
        } catch (DataAccessException error) {
            throw Documents.refusal("Product", error);
        }
        return loaded(entity);
    }

    @Override
    public Product update(Product entity) {
        Document now = Documents.of(mongo, entity);
        Document changes = Documents.changes(LOADED.get(entity), now, FIELDS);
        try {
            if (!changes.isEmpty()) mongo.execute(Product.class, (collection) -> collection.updateOne(Filters.eq("_id", now.get("_id")), changes));
        } catch (DataAccessException error) {
            throw Documents.refusal("Product", error);
        }
        return loaded(entity);
    }

    @Override
    public void delete(Product entity) {
        try {
            mongo.remove(Query.query(Criteria.where("id").is(entity.getId())), Product.class);
        } catch (DataAccessException error) {
            throw Documents.refusal("Product", error);
