    @BeforeEach
    void open() {
        uow = new MongoUnitOfWork(TestDatabase.open());
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            AuditLog stored = Factories.addAuditLog(uow, 1);
            AuditLog found = uow.auditLog().findById(stored.getId()).orElseThrow();
            assertEquals(stored.getId(), found.getId());
        }

        @Test
        void listsRowsByKey() {
            Factories.addAuditLog(uow, 1);
            Factories.addAuditLog(uow, 2);
            var page = uow.auditLog().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void isDeleted() {
            AuditLog stored = Factories.addAuditLog(uow, 1);
            uow.auditLog().delete(stored);
            assertTrue(uow.auditLog().findById(stored.getId()).isEmpty());
        }
    }

    @Nested
    class AuditLogServiceTest {
        private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

        @Test
        void createsAValidRow() {
            AuditLogService service = new AuditLogService(uow);
            int n = 100;
            AuditLog row = Factories.newAuditLog(1);
            var created = service.createAuditLog(createOf(row));
            var found = service.getAuditLog(created.id());
            assertEquals(created.id(), found.id());
        }

        @Test
        void refusesAMissingValue() {
            AuditLogService service = new AuditLogService(uow);
            int n = 100;
            AuditLog row = Factories.newAuditLog(1);
            row.setId(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createAuditLog(createOf(row)));
            assertEquals(List.of("_id"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void saysWhenARowIsMissing() {
            AuditLogService service = new AuditLogService(uow);
            assertThrows(NotFoundException.class, () -> service.getAuditLog("missing"));
        }

        @Test
        void deletesARow() {
            AuditLogService service = new AuditLogService(uow);
            int n = 100;
            AuditLog row = Factories.newAuditLog(1);
            var created = service.createAuditLog(createOf(row));
            service.deleteAuditLog(created.id());
            assertThrows(NotFoundException.class, () -> service.getAuditLog(created.id()));
        }
    }

    /** The create DTO of a row the factories made. */
    private static AuditLogCreate createOf(AuditLog row) {
        return new AuditLogCreate(row.getId(), row.getAt(), row.getBy());
    }
}

