import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

/** Tests of the "products" table. */
class ProductTest {
    /** The repositories over the test database, opened empty for every test */
    private MongoUnitOfWork uow;

    @BeforeEach
    void open() {
        uow = new MongoUnitOfWork(TestDatabase.open());
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            Product stored = Factories.addProduct(uow, 1);
            Product found = uow.products().findById(stored.getId()).orElseThrow();
            assertEquals(stored.getId(), found.getId());
        }

        @Test
        void listsRowsByKey() {
            Factories.addProduct(uow, 1);
            Factories.addProduct(uow, 2);
            var page = uow.products().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void storesTheChanges() {
            Product stored = Factories.addProduct(uow, 1);
            stored.setSku("changed");
            uow.products().update(stored);
            assertEquals("changed", uow.products().findById(stored.getId()).orElseThrow().getSku());
        }

        @Test
        void addsAndRemovesOneItemOfPatterns() {
            Product stored = Factories.addProduct(uow, 1);
            int before = stored.getPatterns() == null ? 0 : stored.getPatterns().size();
            Object item = new java.util.ArrayList<>();
            Product added = uow.products().addPattern(stored.getId(), item).orElseThrow();
            assertEquals(before + 1, added.getPatterns().size());
            Product removed = uow.products().removePattern(stored.getId(), before, added.getPatterns().size()).orElseThrow();
            assertEquals(before, removed.getPatterns().size());
            assertTrue(uow.products().removePattern(stored.getId(), 0, before + 5).isEmpty());
        }

        @Test
        void addsAndRemovesOneItemOfParts() {
            Product stored = Factories.addProduct(uow, 1);
            int before = stored.getParts() == null ? 0 : stored.getParts().size();
            Product.Part item = Factories.newProductPart(7);
            Product added = uow.products().addPart(stored.getId(), item).orElseThrow();
            assertEquals(before + 1, added.getParts().size());
            Product removed = uow.products().removePart(stored.getId(), before, added.getParts().size()).orElseThrow();
            assertEquals(before, removed.getParts().size());
            assertTrue(uow.products().removePart(stored.getId(), 0, before + 5).isEmpty());
        }

        @Test
        void isDeleted() {
            Product stored = Factories.addProduct(uow, 1);
            uow.products().delete(stored);
            assertTrue(uow.products().findById(stored.getId()).isEmpty());
        }
    }

    @Nested
    class ProductServiceTest {
        private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

        @Test
        void createsAValidRow() {
            ProductService service = new ProductService(uow);
            int n = 100;
            Product row = Factories.newProduct(1);
            var created = service.createProduct(createOf(row));
            var found = service.getProduct(created.id());
            assertEquals(created.id(), found.id());
        }

        @Test
        void saysWhenARowIsMissing() {
            ProductService service = new ProductService(uow);
            assertThrows(NotFoundException.class, () -> service.getProduct("ffffffffffffffffffffffff"));
        }

        @Test
        void changesARow() {
            ProductService service = new ProductService(uow);
            int n = 100;
            Product row = Factories.newProduct(1);
            var created = service.createProduct(createOf(row));
            var updated = service.updateProduct(created.id(), new ProductUpdate(Patch.of("changed"), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent()));
            assertEquals("changed", updated.sku());
        }

        @Test
        void addsAndRemovesOneItemOfPatterns() {
            ProductService service = new ProductService(uow);
            int n = 100;
            Product row = Factories.newProduct(1);
            var created = service.createProduct(createOf(row));
            int before = created.patterns() == null ? 0 : created.patterns().size();
            Object item = new java.util.ArrayList<>();
            var added = service.addPattern(created.id(), item);
            assertEquals(before + 1, added.patterns().size());
            var removed = service.removePattern(created.id(), before);
            assertEquals(before, removed.patterns().size());
            assertThrows(NotFoundException.class, () -> service.removePattern(created.id(), 99));
        }

        @Test
        void addsAndRemovesOneItemOfParts() {
            ProductService service = new ProductService(uow);
            int n = 100;
            Product row = Factories.newProduct(1);
            var created = service.createProduct(createOf(row));
            int before = created.parts() == null ? 0 : created.parts().size();
            Product.Part item = Factories.newProductPart(7);
            var added = service.addPart(created.id(), item);
            assertEquals(before + 1, added.parts().size());
            var removed = service.removePart(created.id(), before);
            assertEquals(before, removed.parts().size());
            assertThrows(NotFoundException.class, () -> service.removePart(created.id(), 99));
        }

        @Test
        void deletesARow() {
            ProductService service = new ProductService(uow);
            int n = 100;
            Product row = Factories.newProduct(1);
            var created = service.createProduct(createOf(row));
            service.deleteProduct(created.id());
            assertThrows(NotFoundException.class, () -> service.getProduct(created.id()));
        }
    }

    /** The create DTO of a row the factories made. */
    private static ProductCreate createOf(Product row) {
        return new ProductCreate(row.getSku(), row.getPrice(), row.getStock(), row.getWeight(), row.getBig(), row.getCreated(), row.getReference(), row.getPicture(), row.getKey(), row.getPattern(), row.getPatterns(), row.getText(), row.getParts(), row.getLow());
    }
}

